/* From Uiverse.io by coding-masala - Tags: loader */
.__UIV_SCOPE__ .loading-spinner {
  display: flex;
  align-items: center;
  justify-content: center;
  height: 8em;
}

.__UIV_SCOPE__ .loading-spinner-inner {
  display: flex;
  align-items: center;
  justify-content: center;
}

.__UIV_SCOPE__ .loading-spinner-circle {
  width: 1em;
  height: 1em;
  border-radius: 50%;
  background-color: #db9334;
  margin: 0 5px;
  animation: loading-spinner 1s ease-in-out infinite;
}

.__UIV_SCOPE__ .loading-spinner-circle:nth-child(2) {
  animation-delay: 0.2s;
}

.__UIV_SCOPE__ .loading-spinner-circle:nth-child(3) {
  animation-delay: 0.4s;
}

.__UIV_SCOPE__ .loading-spinner-circle:nth-child(4) {
  animation-delay: 0.6s;
}

.__UIV_SCOPE__ .loading-spinner-circle:nth-child(5) {
  animation-delay: 0.8s;
}

@keyframes loading-spinner {
  0% {
    transform: scale(1);
    opacity: 1;
  }

  20% {
    transform: scale(1.5);
    opacity: 0.5;
  }

  100% {
    transform: scale(1);
    opacity: 1;
  }
}
